date=last.chapterdate;
chapter=last.chaptername;
chapterid=last.chapterid;
result=vip+chapterid+'、'+chapter+'  '+date}

ruleToc.chapterName:
$.chaptername
@js:
result=result.replace(/^\s+/,'');
vip='{{$.isvip}}'!='0';
lock='{{$.islock}}'!='0';
type='{{$.chaptertype}}'=='1';
num=!type?'第{{$.chapterid}}章':'';
if(result.match(/[一二三四五六七八九十百千万\d]+\s*章|晋江|^\d+[、\.\s]|chapter\s*\d+/i)){
result=''}else{result=result}
juan=type?'🍃'+result:result;
l=lock?'[锁]':'';
result=num+'  '+juan+l;
result=!type?result:'';     //不显示卷名

